(()=>{const cfg=window.WPL,by=id=>document.getElementById(id);let data={settings:{},leads:[],users:[],detail:null},activeId=cfg.id||'',calc=null;const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const money=v=>v==null?'—':'$'+Number(v).toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:0});const dt=v=>v?String(v).replace(' ','T').slice(0,16):'';function toast(t){const e=by('status');e.textContent=t;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),2200)}async function api(body){const r=await fetch('api/wholesale-purchasing.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf,Accept:'application/json'},body:JSON.stringify({...body,csrf_token:cfg.csrf})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function load(id=''){const r=await fetch('api/wholesale-purchasing.php'+(id?'?id='+encodeURIComponent(id):''),{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Could not load wholesale planner');data=d;activeId=id||'';renderShell();if(d.detail)renderDetail(d.detail)}function renderShell(){const sel=by('leadSelect'),current=activeId;sel.innerHTML='<option value="">Select a lead…</option>'+data.leads.map(l=>`<option value="${esc(l.public_id)}">${esc(l.business_name)} · ${esc(l.pipeline_stage)}</option>`).join('');sel.value=current;const owner=by('ownerUserId'),chosen=owner.value;owner.innerHTML='<option value="">Unassigned</option>'+data.users.map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('');owner.value=chosen;renderSettings(data.settings||{})}function renderSettings(s){[['panLiters','pan_liters'],['defaultServingOz','default_serving_oz'],['defaultSafetyStockPercent','default_safety_stock_percent'],['defaultWastePercent','default_waste_percent'],['weeksPerMonth','weeks_per_month'],['coreWeeklyPans'