_weekly_pans!=null)by('existingWeeklyPans').value=w.existing_weekly_pans;if(w.safety_stock_percent!=null)by('safetyStockPercent').value=w.safety_stock_percent;if(w.waste_percent!=null)by('wastePercent').value=w.waste_percent;if(w.menu_price_per_serving!=null)by('menuPricePerServing').value=w.menu_price_per_serving;if(w.freezer_pan_capacity!=null)by('freezerPanCapacity').value=w.freezer_pan_capacity;if(w.delivery_frequency)by('deliveryFrequency').value=w.delivery_frequency;by('worksheetNotes').value=w.notes||'';by('lifecycleStage').value=l.lifecycle_stage||'discovery';by('ownerUserId').value=l.owner_user_id||'';by('nextAction').value=l.next_action||'';by('nextActionAt').value=dt(l.next_action_at);by('lifecycleNotes').value=l.lifecycle_notes||'';renderCatalog(d.catalog||[],Array.isArray(w.starter_order_json)?w.starter_order_json:[]);renderTastings(d.tastings||[]);const existingOrder=w.starter_order_public_id||'';by('createOrder').disabled=!d.canCreateOrder;by('createOrder').textContent=existingOrder?'Starter order already created':'Create requested starter order';by('orderGuard').textContent=existingOrder?`Starter order ${existingOrder} is linked to this worksheet. Re-running the action safely returns the same order.`:(d.canCreateOrder?'This lead has an active Wholesale account. Creating the starter order writes a requested order into the canonical Wholesale order flow.':'Convert this lead to an active Wholesale account before creating a real starter order. The worksheet itself can still be saved now.');if(w.id)renderCalc({weeklyLiters:Number(w.weekly_liters),recommendedWeeklyPans:Number(w.recommended_weekly_pans),recommendedMonthlyPans:Number(w.recommended_monthly_pans),accountTier:w.account_tier,projectedMonthlyWholesaleSpend:w.projected_monthly_wholesale_spend!=null?Number(w.projected_monthly_wholesale_spend):null,projectedMonthlyGrossProfit:w.projected_monthly_gross_profit!=null?Number(w.projected_monthly_gross_profit):null,warnings:w.assumptions_json?.warnings||[]})}function renderCatalog(rows,starter){const map=Object.fromEntries(starter.map(x=>[String(x.skuId),x]));by('catalogRows').innerHTML=rows.length?rows.map(r=>{const saved=map[String(r.id)],checked=!!saved,qty=saved?.quantity??'';return `<tr><td><input type="checkbox" data-sku-check="${esc(r.id)}" ${checked?'checked':''}></td><td><strong>${esc(r.name)}</strong><br><small>${esc(r.sku)} · ${esc(r.productName||'')}</small></td><td>${esc(r.sellUom)}</td><td>${r.unitPrice==null?'<span class="tag">Unpriced</span>':money(r.unitPrice)}</td><td><input class="qty" data-sku-qty="${esc(r.id)}" type="number" min="0" step="${Number(r.quantityIncrement||1)}" value="${esc(qty)}"></td></tr>`}).join(''):'<tr><td colspan="5"><div class="empty">No active Wholesale SKUs are configured.</div></td></tr>'}function renderCalc(c){calc=c;by('mWeekly').textContent=Number(c.recommendedWeeklyPans||0).toLocaleString();by('mMonthly').textContent=Number(c.recommendedMonthlyPans||0).toLocaleString(undefined,{maximumFractionDigits:1});by('mTier').textContent=String(c.accountTier||'—').replace(/^./,x=>x.toUpperCase());by('mSpend').textContent=money(c.projectedMonthlyWholesaleSpend);by('mProfit').textContent=money(c.projectedMonthlyGrossProfit);by('mLiters').textContent=Number(c.weeklyLiters||0).toFixed(1)+' L/week';const cap=Number(by('freezerPanCapacity').value||0);by('mCapacity').textContent=cap?`${c.recommendedWeeklyPans||0} planned / ${cap} pan capacity`:'Based on weekly pans';by('calcWarnings').innerHTML=(c.warnings||[]).map(w=>`<div class="note warning">${esc(w)}</div>`).join('')||'<div class="note good">Demand model is internally consistent with current inputs.</div>'}function renderTastings(rows){by('tastingList').innerHTML=rows.length?rows.map(t=>`<article class="taste"><strong>${esc(t.status)} · ${esc(t.tasting_format)}${t.overall_score?' · '+esc(t.overall_score)+'/5':''}</strong><p>${esc((t.flavors||[]).join(', ')||'No flavors recorded')}${t.outcome?' · Outcome: '+esc(t.outcome):''}</p><small>${esc(t.scheduled_at||t.created_at)}</small></article>`).join(''):'<div class="empty">No tasting records yet.</div>'}by('leadSelect').onchange=async()=>{activeId=by('leadSelect').value;if(!activeId){history.replaceState({},'', 'wholesale-purchasing.php');data.detail=null;return}history.replaceState({},'',`wholesale-purchasing.php?id=${encodeURIComponent(activeId)}`);try{await load(activeId)}catch(e){toast(e.message)}};by('calculate').onclick=async()=>{if(!activeId)return toast('Select a Wholesale opportunity first.');try{const d=await api(worksheetPayload('worksheet.calculate'));renderCalc(d.calculation);const saved=data.detail?.worksheet?.starter_order_json||[];renderCatalog(data.detail?.catalog||[],d.calculation.starterItems?.length?d.calculation.starterItems:saved)}catch(e){toast(e.message)}};by('saveWorksheet').onclick=async()=>{if(!activeId)return toast('Select a Wholesale opportunity first.');try{const d=await api(worksheetPayload('worksheet.save'));renderCalc(d.calculation);renderDetail(d.detail);toast(d.message)}catch(e){toast(e.message)}};by('saveLifecycle').onclick=async()=>{if(!activeId)return toast('Select a Wholesale opportunity first.');try{const d=await api({action:'lifecycle.save',leadId:activeId,lifecycleStage:by('lifecycleStage').value,ownerUserId:by('ownerUserId').value,nextAction:by('nextAction').value,nextActionAt:by('nextActionAt').value,lifecycleNotes:by('lifecycleNotes').value});renderDetail(d.detail);toast(d.message)}catch(e){toast(e.message)}};by('saveTasting').onclick=async()=>{if(!activeId)return toast('Select a Wholesale opportunity first.');try{const d=await api({action:'tasting.save',leadId:activeId,status:by('tastingStatus').value,tastingFormat:by('tastingFormat').value,scheduledAt:by('scheduledAt').value,attendees:by('attendees').value,flavors:by('tastingFlavors').value.split(',').map(x=>x.trim()).filter(Boolean),overallScore:by('overallScore').value,outcome:by('tastingOutcome').value,notes:by('tastingNotes').value,nextAction:by('tastingNextAction').value,nextActionAt:by('tastingNextActionAt').value});renderDetail(d.detail);toast(d.message)}catch(e){toast(e.message)}};by('createOrder').onclick=async()=>{if(!activeId)return;try{const d=await api({action:'starter_order.create',leadId:activeId});renderDetail(d.detail);toast(`${d.message} ${d.order.orderNumber}`)}catch(e){toast(e.message)}};by('saveSettings').onclick=async()=>{try{const d=await api({action:'settings.save',panLiters:by('panLiters').value,defaultServingOz:by('defaultServingOz').value,defaultSafetyStockPercent:by('defaultSafetyStockPercent').value,defaultWastePercent:by('defaultWastePercent').value,weeksPerMonth:by('weeksPerMonth').value,coreWeeklyPans:by('coreWeeklyPans').value,growthWeeklyPans:by('growthWeeklyPans').value,keyWeeklyPans:by('keyWeeklyPans').value});data.settings=d.settings;renderSettings(d.settings);toast(d.message)}catch(e){toast(e.message)}};load(activeId).catch(e=>toast(e.message))})();
</script></body></html>
